export const names=['Bench press','Deadlift','Squat rack','Dumbbells'];
export function parseGraph(g){if(g.source!=='MCNS v1.0'||!Array.isArray(g.neurons)||!Array.isArray(g.edges))throw Error('Expected source MCNS v1.0, neurons and edges.');if(g.neurons.length<2||g.neurons.length>5000||g.edges.length<1||g.edges.length>50000)throw Error('Use 2–5,000 neurons and 1–50,000 edges.');if(g.neurons.some(n=>typeof n!=='string'||!n.length)||new Set(g.neurons).size!==g.neurons.length)throw Error('Neuron IDs must be unique, nonempty strings.');const index=new Map(g.neurons.map((n,i)=>[n,i]));const edges=g.edges.map(e=>{if(!index.has(e.pre)||!index.has(e.post)||!Number.isFinite(e.weight)||Math.abs(e.weight)>1e9)throw Error('Invalid edge endpoint or weight.');return[index.get(e.pre),index.get(e.post),e.weight]});return makeNetwork(g.neurons.length,edges,true)}
export function makeNetwork(n=24,edges=null,imported=false){if(!edges)edges=Array.from({length:n*3},(_,i)=>[i%n,(i*7+3)%n,Math.sin(i*2.4)]);const totals=new Float64Array(n);for(const[a,b,w]of edges)totals[b]+=Math.abs(w);return{n,imported,activity:new Float64Array(n),edges:edges.map(([a,b,w])=>[a,b,w/Math.max(1,totals[b])])}}
export function tickNetwork(net,energy,fatigue,time){const next=new Float64Array(net.n);for(let i=0;i<net.n;i++)next[i]=.2+energy/250-fatigue/300+Math.sin(time*.7+i*1.7)*.35;for(const[a,b,w]of net.edges)next[b]+=net.activity[a]*w;for(let i=0;i<net.n;i++)net.activity[i]=.7*net.activity[i]+.3*Math.tanh(next[i]);return Array.from({length:4},(_,k)=>{let s=0,n=0;for(let i=k;i<net.n;i+=4){s+=net.activity[i];n++}return n?s/n:0})}
export function initial(){return{time:0,energy:100,fatigue:0,mass:1,sets:0,reps:0,station:0,phase:'walking',phaseTime:0,counts:[0,0,0,0],lastBoost:-30,x:0,y:0,targetX:-2.5,targetY:-1.8,route:[[-2.5,0],[-2.5,-1.8]]}}
export const positions=[[-2.5,-1.8],[2.4,1.7],[2.4,-1.8],[-2.5,1.7]];
export function step(s,dt,net,onEvent=()=>{}){s.time+=dt;s.phaseTime+=dt;const scores=tickNetwork(net,s.energy,s.fatigue,s.time);if(s.phase==='walking'){const [tx,ty]=s.route?.[0]??[s.targetX,s.targetY];const dx=tx-s.x,dy=ty-s.y,d=Math.hypot(dx,dy),v=dt*.9;if(d<=v){s.x=tx;s.y=ty;if(s.route?.length)s.route.shift();if(!s.route?.length){s.phase='lifting';s.phaseTime=0;onEvent('Started '+names[s.station].toLowerCase()+'.')}}else{s.x+=dx/d*v;s.y+=dy/d*v}}
else if(s.phase==='lifting'){s.energy=Math.max(0,s.energy-dt*1.1);s.fatigue=Math.min(100,s.fatigue+dt*.85);if(s.phaseTime>=12){s.phaseTime=0;s.sets++;s.reps+=8;s.counts[s.station]++;s.mass+=.012/(1+(s.mass-1)*.3);onEvent('8 reps. Tiny gains acquired.');s.phase='resting'}}
else{s.energy=Math.min(100,s.energy+dt*3);s.fatigue=Math.max(0,s.fatigue-dt*3.5);if(s.phaseTime>6&&s.energy>65&&s.fatigue<35){s.station=scores.map((v,k)=>v-s.counts[k]*.15+(k!==s.station?.12:0)).reduce((best,v,k,a)=>v>a[best]?k:best,0);[s.targetX,s.targetY]=positions[s.station];s.route=[[s.x,0],[s.targetX,0],[s.targetX,s.targetY]];s.phase='walking';s.phaseTime=0}}return scores}
